// BIM 법규검토: IFC reading, geometric measurement and the KR rule set on the two
// sample models (public/bim/*.ifc, generated by scripts/make-test-ifc.py).
import assert from "node:assert/strict";
import fs from "node:fs";
import { before, test } from "node:test";
import * as WebIFC from "web-ifc";
import { analyze } from "../lib/bim/analyze.ts";
import { classifySpace } from "../lib/bim/convention.ts";
import { Grid, minAreaRect, rayToPolygon, walkDistances } from "../lib/bim/geometry.ts";
import { readIfc } from "../lib/bim/ifc-read.ts";
import * as L from "../lib/bim/law-parse.ts";
import { reviewBim } from "../lib/bim/rules.ts";
import type { BimFacts } from "../lib/bim/types.ts";
import { loadNational } from "../lib/corpus.ts";

const api = new WebIFC.IfcAPI();
const facts: Record<string, BimFacts> = {};
const truth = (name: string) => JSON.parse(fs.readFileSync(`tests/bim/${name}.truth.json`, "utf8"));
const near = (a: number, b: number, tol: number, what: string) => assert.ok(Math.abs(a - b) <= tol, `${what}: ${a} ≠ ${b} (±${tol})`);

before(async () => {
  await api.Init();
  for (const name of ["sample-a-compliant", "sample-b-violations"]) {
    const model = readIfc(api, new Uint8Array(fs.readFileSync(`public/bim/${name}.ifc`)));
    facts[name] = analyze(model, { file: `${name}.ifc` }).facts;
  }
});

test("statute parsers read today's thresholds from the corpus", () => {
  const t = (id: string) => loadNational().byId.get(id)!.text;
  assert.deepEqual(L.egressLimits(t("건축법시행령#34"))?.base, 30);
  assert.deepEqual(L.egressLimits(t("건축법시행령#34"))?.fire, 50);
  assert.deepEqual(L.twoStairItems(t("건축법시행령#34")).map(x => x.area), [200, 200, 300, 400, 200]);
  const w = L.stairWidths(t("건축물의피난방화구조등의기준에관한규칙#15"));
  assert.equal(w.upper?.width, 1.2);
  assert.equal(w.other?.width, 0.6);
  assert.equal(w.elementary?.riser, 0.16);
  assert.deepEqual(L.corridorTable(t("건축물의피난방화구조등의기준에관한규칙#15의2")).housing, [1.8, 1.2]);
  assert.equal(L.ceilingRule(t("건축물의피난방화구조등의기준에관한규칙#16"))?.min, 2.1);
  assert.equal(L.windowRatios(t("건축물의피난방화구조등의기준에관한규칙#17"))?.light, 0.1);
  assert.equal(L.parkingStalls(t("주차장법시행규칙#3")).일반형?.width, 2.5);
  assert.equal(L.housingStair(t("주택건설기준등에관한규정#16"))?.tread, 0.26);
  assert.equal(L.roofGuard(t("건축법시행령#40"))?.height, 1.2);
});

test("geometry: walking distance, rectangles, north ray", () => {
  const g = new Grid(0, 0, 1, 10, 10);
  const d = walkDistances(g, new Uint8Array(g.size).fill(1), [0]);
  near(d[99], Math.hypot(9, 9), 0.01, "diagonal");
  near(d[9 * 10 + 3], Math.hypot(3, 9), 0.3, "any-angle");
  const r = minAreaRect([[0, 0], [4, 0], [4, 1], [0, 1]]);
  near(r.length, 4, 1e-9, "length"); near(r.width, 1, 1e-9, "width");
  assert.ok(Math.abs(r.u[0] * r.v[0] + r.u[1] * r.v[1]) < 1e-9, "u ⟂ v");
  near(rayToPolygon(5, 5, [0, 1], [[0, 0], [10, 0], [10, 20], [0, 20]])!, 15, 1e-9, "north ray");
  assert.equal(classifySpace("101", "복도").use, "복도");
  assert.equal(classifySpace("101", "Living Room").use, "거실");
  assert.equal(classifySpace("101", "창고", "계단실").source, "property");
});

for (const name of ["sample-a-compliant", "sample-b-violations"]) {
  test(`${name}: measured values match the drawing`, () => {
    const f = facts[name], t = truth(name);
    assert.equal(f.building.storeysAbove, t.storeys_above);
    assert.equal(f.building.storeysBelow, t.storeys_below);
    near(f.building.height, t.height, 0.01, "height");
    near(f.building.footprint, t.building_area, t.building_area * 0.005, "건축면적");
    near(f.building.grossFloorArea, t.gross_floor_area, t.gross_floor_area * 0.005, "연면적");
    near(f.site.area!, t.site_area, 0.01, "대지면적");
    assert.equal(f.parking.length, t.parking);
    near(f.building.landscapeArea!, t.landscape_area, 0.5, "조경면적");
    const maxEgress = Math.max(...f.egress.flatMap(e => e.spaces.map(s => s.maxDistance ?? 0)));
    assert.ok(maxEgress >= t.egress_max[0] && maxEgress <= t.egress_max[1], `보행거리 ${maxEgress}`);
    if (t.north_min_low !== undefined) near(f.north.minLow!.d, t.north_min_low, 0.01, "정북 이격(10m 이하)");
    if (t.north_min_high !== undefined) near(f.north.minHigh!.d, t.north_min_high, 0.01, "정북 이격(10m 초과)");
    for (const st of f.stairs) for (const fl of st.flights) assert.ok(fl.width > 0.9 && fl.width < 1.3, `${fl.ref.name} width ${fl.width}`);
  });

  test(`${name}: rule set verdicts`, async () => {
    const r = await reviewBim({ facts: facts[name] });
    const fails = r.rules.filter(x => x.status === "FAIL").map(x => x.check_id).sort();
    const expected = (truth(name).expect.FAIL as string[]).slice().sort();
    assert.deepEqual(fails, expected);
    for (const rule of r.rules) {
      for (const i of rule.issues) assert.ok(i.status === "FAIL" || i.status === "UNCLEAR");
      if (rule.status === "FAIL") assert.ok(rule.citations.some(c => c.verified) || rule.code_confidence !== "HIGH", `${rule.check_id}: FAIL without a verified citation`);
    }
    assert.ok(r.md.includes("BIM 법규검토 보완요구서(안)"));
  });
}

test("정북 일조 falls back to entered setbacks when the model has no site boundary", async () => {
  const f: BimFacts = structuredClone(facts["sample-b-violations"]);
  f.north = { available: false, reason: "대지경계선이 없습니다.", frontier: [], perElement: [] };
  f.site.boundary = undefined;
  const none = await reviewBim({ facts: f });
  assert.equal(none.rules.find(r => r.check_id === "B-NORTH")?.status, "UNCLEAR");
  const typed = await reviewBim({ facts: f, values: { 정북이격_10m이하: { value: 6, source: "user", confidence: "HIGH" }, 정북이격_10m초과: { value: 6, source: "user", confidence: "HIGH" } } });
  assert.equal(typed.rules.find(r => r.check_id === "B-NORTH")?.status, "FAIL");
});
